CREATE TABLE ezcontentobject (id SERIAL NOT NULL, contentclass_id INT DEFAULT 0 NOT NULL, current_version INT DEFAULT NULL, initial_language_id BIGINT DEFAULT 0 NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, modified INT DEFAULT 0 NOT NULL, name VARCHAR(255) DEFAULT NULL, owner_id INT DEFAULT 0 NOT NULL, published INT DEFAULT 0 NOT NULL, remote_id VARCHAR(100) DEFAULT NULL, section_id INT DEFAULT 0 NOT NULL, status INT DEFAULT 0, is_hidden BOOLEAN DEFAULT 'false' NOT NULL, PRIMARY KEY(id));
